public void new()
{
    super();

    this.parmClassName(classStr(METSalesOrderCancellationService));
    this.parmMethodName(methodStr(METSalesOrderCancellationService, process));
    this.parmDialogCaption("Sales order cancellation");
    this.parmExecutionMode(SysOperationExecutionMode::Asynchronous);
}

public static METSalesOrderCancellationController construct()
{
    return new METSalesOrderCancellationController();
}

/// <summary>
/// Entry point for scheduling from the batch job form
/// (System administration > Inquiries > Batch jobs > New task,
/// or via Recurring integrations scheduling battery as applicable).
/// </summary>
public static void main(Args _args)
{
    METSalesOrderCancellationController controller = METSalesOrderCancellationController::construct();
    controller.startOperation();
}
